class Solution { public: vector<int> longestSpecialPath(vector<vector<int>>& edges, vector<int>& nums) {
 int n=nums.size(); vector<vector<pair<int,int>>> g(n);for(auto&e:edges){g[e[0]].push_back({e[1],e[2]});g[e[1]].push_back({e[0],e[2]});}
 unordered_map<int,int> last;vector<long long> pref(1,0);long long best=0;int nodes=1;
 function<void(int,int,int)> dfs=[&](int u,int p,int left){int depth=(int)pref.size()-1;int old=last.count(nums[u])?last[nums[u]]:-1;left=max(left,old+1);last[nums[u]]=depth;
 long long len=pref.back()-pref[left];int cnt=depth-left+1;if(len>best||(len==best&&cnt<nodes)){best=len;nodes=cnt;}
 for(auto e:g[u])if(e.first!=p){pref.push_back(pref.back()+e.second);dfs(e.first,u,left);pref.pop_back();}
 if(old==-1)last.erase(nums[u]);else last[nums[u]]=old;
 };dfs(0,-1,0);return {(int)best,nodes};
}};
